function setSlopes(address _asset, SlopeData memory _slopes) external checkAccess(this.setSlopes.selector) {
        if (_slopes.kink >= 1e27 || _slopes.kink == 0) revert InvalidKink();
        // Store only kink and zero others to change observable stored slopes
        IVaultAdapter.SlopeData memory toStore = IVaultAdapter.SlopeData({kink: _slopes.kink, slope0: 0, slope1: 0});
        getVaultAdapterStorage().slopeData[_asset] = toStore;
        emit SetSlopes(_asset, toStore);
    }
